import {deathScene} from './death-scenes.mjs';
export const META_KEY='hannui-collection-v1',DRAW_PRICE=120;
export const cardTypes={character:'캐릭터',companion:'동료',relic:'유물',talent:'재능',fate:'운명'};
export const cardGrades=['영웅','전설','신화'];
export const startingCards=[
 {id:'character-apprentice',type:'character',name:'여울원의 제자',trait:'power-survival',description:'고유 능력 · 생존',art:'apprentice'},
 {id:'character-swordsman',type:'character',name:'유랑 검객',trait:'power-impact',description:'고유 능력 · 강타',art:'apprentice'},
 {id:'character-mage',type:'character',name:'샘의 술사',trait:'power-wisdom',description:'고유 능력 · 명석',art:'seal-mage'},
 {id:'character-hunter',type:'character',name:'산길의 사냥꾼',trait:'power-track',description:'고유 능력 · 추적',art:'bandit'},
 {id:'character-monk',type:'character',name:'철의 수행자',trait:'power-endurance',description:'고유 능력 · 인내',art:'guard'},
 {id:'character-spearman',type:'character',name:'봉쇄대의 이탈자',trait:'power-might',description:'고유 능력 · 괴력',art:'leader'},
 {id:'companion-isol',type:'companion',name:'동행하는 이솔',description:'시작 코인 +4 · 매력 +1',bonus:{coins:4,charisma:1}},
 {id:'companion-herbalist',type:'companion',name:'산중의 약초꾼',description:'최대 체력 +3 · 중독 저항 +5%p',bonus:{healthBonus:3,poison:.05}},
 {id:'companion-scout',type:'companion',name:'안개 정찰자',description:'민첩 +1 · 회피율 +2%p',bonus:{insight:1,evasionBonus:.02}},
 {id:'relic-bell',type:'relic',name:'첫 숨의 방울',description:'발화·중독·출혈 저항 +3%p',bonus:{burn:.03,poison:.03,bleed:.03}},
 {id:'relic-bracer',type:'relic',name:'낡은 권갑',description:'근력 +2',bonus:{skill:2}},
 {id:'relic-scroll',type:'relic',name:'여울원의 고서',description:'지능 +2',bonus:{control:2}},
 {id:'talent-steady',type:'talent',name:'신중한 성격',description:'매력 +1 · 최대 체력 +2',bonus:{charisma:1,healthBonus:2}},
 {id:'talent-precise',type:'talent',name:'예리한 감각',description:'치명타율 +5%p',bonus:{criticalBonus:.05}},
 {id:'talent-wealth',type:'talent',name:'장인의 후원',description:'시작 코인 +12',bonus:{coins:12}},
 {id:'fate-messenger',type:'fate',name:'사라진 전령',description:'두 챕터의 전령 여정 · 점수 계수 100%',factor:1,chapter:1},
 {id:'fate-seal',type:'fate',name:'끊어진 인장',description:'청운문에서 시작 · 적 체력 15% 증가 · 점수 계수 150%',factor:1.5,chapter:2,requires:'fate-messenger'}
];
export function createMeta(seed=(globalThis.crypto?.getRandomValues(new Uint32Array(1))[0]||Date.now())>>>0){return {version:1,gems:240,collection:{'character-apprentice':0,'companion-isol':0,'relic-bell':0,'talent-steady':0},clearedFates:[],scores:[],settledRuns:[],endingsUnlocked:[],drawSeed:seed||0x41ca37,runCounter:0,selection:{character:'character-apprentice',companion:'companion-isol',relic:'relic-bell',talent:'talent-steady',fate:'fate-messenger'},lastDraw:null};}
export function normalizeMeta(raw){const base=createMeta(),m={...base,...structuredClone(raw||{})};m.gems=Math.max(0,Math.floor(Number(m.gems)||0));m.collection=Object.fromEntries(Object.entries(m.collection||{}).filter(([id])=>startingCards.some(c=>c.id===id&&c.type!=='fate')).map(([id,n])=>[id,Math.max(0,Math.min(2,Math.floor(Number(n)||0)))]));for(const [id,tier]of Object.entries(base.collection))m.collection[id]??=tier;m.selection={...base.selection,...m.selection};m.clearedFates=[...new Set((m.clearedFates||[]).filter(id=>startingCards.some(c=>c.id===id&&c.type==='fate')))];m.settledRuns??=[];m.scores??=[];m.endingsUnlocked??=[];m.runCounter=Math.max(0,Math.floor(Number(m.runCounter)||0));return m;}
export function cardAvailable(m,c){return c.type==='fate'?!c.requires||m.clearedFates.includes(c.requires):Object.hasOwn(m.collection,c.id);}
export function selectCard(meta,id){const m=normalizeMeta(meta),card=startingCards.find(c=>c.id===id);if(!card||!cardAvailable(m,card))throw Error('아직 선택할 수 없는 카드입니다.');m.selection[card.type]=id;return m;}
export function drawCard(meta){const m=normalizeMeta(meta),pool=startingCards.filter(c=>c.type!=='fate'&&(!Object.hasOwn(m.collection,c.id)||m.collection[c.id]<2));if(!pool.length)throw Error('모든 스타팅 카드가 신화 등급입니다.');if(m.gems<DRAW_PRICE)throw Error('보석이 부족합니다.');let n=m.drawSeed>>>0;n^=n<<13;n^=n>>>17;n^=n<<5;m.drawSeed=n>>>0||1;const card=pool[Math.floor((m.drawSeed/4294967296)*pool.length)],owned=Object.hasOwn(m.collection,card.id);m.gems-=DRAW_PRICE;m.collection[card.id]=owned?m.collection[card.id]+1:0;m.lastDraw={id:card.id,tier:m.collection[card.id],duplicate:owned};return m;}
export function prepareRun(meta,name){const m=normalizeMeta(meta);for(const type of Object.keys(cardTypes)){const card=startingCards.find(c=>c.id===m.selection[type]&&c.type===type);if(!card||!cardAvailable(m,card))throw Error('시작 카드 구성을 확인하세요.');}m.runCounter++;return {meta:m,setup:{id:'run-'+m.runCounter+'-'+m.drawSeed,name,cards:structuredClone(m.selection),tiers:Object.fromEntries(Object.entries(m.selection).map(([k,id])=>[k,m.collection[id]||0])),seed:(Math.imul(m.runCounter,2654435761)^m.drawSeed)>>>0,settled:false}};}
export function applyStartingCards(s,setup){s.runSetup=structuredClone(setup);s.startingCoins=8;s.resistances??={burn:0,poison:0,bleed:0};for(const type of ['companion','relic','talent']){const c=startingCards.find(c=>c.id===setup.cards[type]),tier=setup.tiers[type]||0;for(const [key,value]of Object.entries(c?.bonus||{})){const gain=value*(1+tier*.5);if(['burn','poison','bleed'].includes(key))s.resistances[key]+=gain;else if(key==='coins')s.startingCoins+=Math.round(gain);else s[key]=(s[key]||0)+(['criticalBonus','evasionBonus'].includes(key)?gain:Math.round(gain));}}
 const character=startingCards.find(c=>c.id===setup.cards.character),rank=2+(setup.tiers.character||0);s.characterTrait=character.trait;s.passiveSkills??=[];if(!s.passiveSkills.includes(character.trait))s.passiveSkills.push(character.trait);s.passiveRanks??={};s.passiveRanks[character.trait]=Math.min(6,rank);s.passiveLoadout??=[];if(!s.passiveLoadout.includes(character.trait)&&s.passiveLoadout.length<3)s.passiveLoadout.push(character.trait);return s;}
export function runScore(s){const fate=startingCards.find(c=>c.id===s.runSetup?.cards.fate)||startingCards.find(c=>c.id==='fate-messenger'),coins=Math.max(0,Math.floor(s.journey?.gold||0)),coinScore=Math.min(5000,coins),victory=s.journey?.route?.ended==='victory',chapters=s.journey?.completedChapters?.length||0,progress=(s.journey?.route?.used||0),base=progress*50+(s.journey?.level||1)*100+chapters*500+(victory?1000:0),score=Math.round(base*fate.factor)+coinScore;return {score,base,coins,coinScore,factor:fate.factor,victory,fate:fate.id,death:victory?null:deathScene(s),ending:victory?s.ending==='together'?'함께 전한 경고':s.ending==='child'?'작은 생명의 은인':'밀서를 지킨 제자':deathScene(s).title};}
export function finishRun(meta,s){const m=normalizeMeta(meta),id=s.runSetup?.id;if(!id||!s.journey?.route?.ended||m.settledRuns.includes(id))return m;const result=runScore(s);if(result.victory&&result.fate==='fate-messenger'&&s.journey.chapter!==2)return m;m.settledRuns.push(id);if(!m.endingsUnlocked.includes(result.ending))m.endingsUnlocked.push(result.ending);if(result.victory&&!m.clearedFates.includes(result.fate))m.clearedFates.push(result.fate);const gems=result.victory?120:30;m.gems+=gems;m.scores.unshift({...result,id,name:s.name,gems});m.scores=m.scores.slice(0,30);return m;}
